try {
  var config = $('⚙️ Client Config').first().json;
  var allClients = $('Read Clients').all().map(function(item) { return item.json; });
  var allReactivation = $('Read Reactivation Log').all().map(function(item) { return item.json; });

  // Leads already in Reactivation Log with these statuses are excluded from re-enqueue.
  // call-failed is intentionally NOT in this list — VAPI fire failures should be retried
  // by D5-WF1 on the next daily run (WF2e already logged the failure).
  var activeStatuses = ['queued', 'call-initiated', 'retry-pending', 'declined-final', 'exhausted', 'interested-callback', 'booked', 'opted-out', 'completed'];
  var activePhones = {};
  allReactivation.forEach(function(row) {
    if (activeStatuses.indexOf(row['Reactivation Status']) !== -1) {
      activePhones[row['Phone']] = true;
    }
  });

  var now = new Date();
  var cooldownMs = config.cooldownDays * 24 * 60 * 60 * 1000;

  var excludeStatuses = [
    'do-not-contact', 'not-interested', 'sequence-active',
    'call-initiated', 'callback-scheduled', 'inbound-incomplete', 'booked'
  ];
  var idleStatuses = ['unresponsive', 'called', 'voicemail', 'no-answer'];

  var results = [];

  allClients.forEach(function(lead) {
    if (!lead['Phone']) return;
    if (excludeStatuses.indexOf(lead['Status']) !== -1) return;
    if (idleStatuses.indexOf(lead['Status']) === -1) return;
    if (lead['SMS Opt-Out'] === 'Y') return;
    if (activePhones[lead['Phone']]) return;

    var lastContact = lead['Last Contact'] ? new Date(lead['Last Contact']) : null;
    if (lastContact && (now - lastContact) < cooldownMs) return;

    if (lead['Status'] === 'unresponsive' && lead['Unresponsive Since']) {
      var unresponsiveSince = new Date(lead['Unresponsive Since']);
      if ((now - unresponsiveSince) < cooldownMs) return;
    }

    var createdAt = lead['Created At'] ? new Date(lead['Created At']) : now;
    var retentionDeadline = new Date(createdAt.getTime() + (config.retentionMonths * 30 * 24 * 60 * 60 * 1000));

    var angle = 'promo';
    var serviceInterest = (lead['Service Interest'] || '').toLowerCase();
    if (serviceInterest.indexOf('solar') !== -1) {
      angle = 'net-metering';
    } else if (serviceInterest.indexOf('batter') !== -1) {
      angle = 'battery-storage';
    }

    results.push({
      json: {
        'Phone':                lead['Phone'],
        'Name':                 lead['Name'] || '',
        'Email':                lead['Email'] || '',
        'Service Interest':     lead['Service Interest'] || '',
        'Pool Type':            'idle',
        'Channel':              'voice',
        'Campaign ID':          'auto-' + now.toISOString().split('T')[0],
        'Reactivation Status':  'queued',
        'Attempt Count':        0,
        'Last Touch':           '',
        'Last Channel':         '',
        'Next Touch At':        '',
        'Callback Preference':  '',
        'Transcript URL':       '',
        'Call Duration':        '',
        'Completed At':         '',
        'Created At':           now.toISOString(),
        'Import Source':        'auto',
        'Reactivation Angle':   angle,
        'Error Notes':          '',
        'Consent Basis':        'legitimate-interest-prior-enquiry',
        'Retention Deadline':   retentionDeadline.toISOString(),
        'Original Lead Date':   lead['Created At'] || ''
      }
    });
  });

  results.sort(function(a, b) {
    return new Date(a.json['Retention Deadline']) - new Date(b.json['Retention Deadline']);
  });

  return results.length > 0 ? results : [{ json: { _empty: true } }];
} catch (e) {
  return [{ json: { _empty: true, _error: e.message } }];
}
